mapper.sql:
WHERE account_id = #{accountId}
  AND in_app
  AND (read_at IS NULL OR read_at > #{readCutoff})

  AND (title ILIKE #{pattern} ESCAPE '\' OR message ILIKE #{pattern} ESCAPE '\')


  AND category IN
  #{category}

mapper.update:
UPDATE notification
SET read_at = COALESCE(read_at, #{readAt})
WHERE notification_id = #{notificationId}
  AND account_id = #{accountId}
  AND in_app

mapper.select:
SELECT notification_id, account_id, category, title, message, channels, created_at, read_at
FROM notification
WHERE notification_id = #{notificationId}
  AND account_id = #{accountId}
  AND in_app
